package cue

import (
	_ "embed"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"strings"

	yamlv3 "gopkg.in/yaml.v3"

	"cuelang.org/go/cue"
	"cuelang.org/go/cue/cuecontext"
	cueerror "cuelang.org/go/cue/errors"
	"cuelang.org/go/encoding/yaml"
)

const (
	jsonFormat = "json"
	textFormat = "text"
)

var (
	//go:embed flipt.cue
	cueFile             []byte
	ErrValidationFailed = errors.New("validation failed")
)

// Result contains all errors found while validating a document.
type Result struct {
	Errors []Error `json:"errors"`
}

// FeaturesValidator validates YAML feature documents against the embedded schema.
type FeaturesValidator struct {
	cue *cue.Context
	v   cue.Value
}

// NewFeaturesValidator compiles the embedded schema.
func NewFeaturesValidator() (*FeaturesValidator, error) {
	cctx := cuecontext.New()
	v := cctx.CompileBytes(cueFile)
	if err := v.Err(); err != nil {
		return nil, fmt.Errorf("compile features schema: %w", err)
	}
	return &FeaturesValidator{cue: cctx, v: v}, nil
}

// ValidateBytes validates YAML against the feature schema.
func ValidateBytes(b []byte) error {
	v, err := NewFeaturesValidator()
	if err != nil {
		return err
	}
	_, err = v.Validate("", b)
	return err
}

// Location identifies a position in the original YAML source.
type Location struct {
	File   string `json:"file,omitempty"`
	Line   int    `json:"line"`
	Column int    `json:"column"`
}

// Error describes a validation failure and its YAML source location.
type Error struct {
	Path     string   `json:"path"`
	Message  string   `json:"message"`
	Location Location `json:"location"`
}

// Validate checks a YAML document and returns every error found by CUE.
func (v *FeaturesValidator) Validate(file string, b []byte) (Result, error) {
	result := Result{Errors: []Error{}}
	f, err := yaml.Extract(file, b)
	if err != nil {
		return errorsResult(file, err, nil)
	}

	yv := v.v.Unify(v.cue.BuildFile(f, cue.Scope(v.v)))
	if err := yv.Validate(cue.All()); err != nil {
		return errorsResult(file, err, sourcePositions(b))
	}
	return result, nil
}

type sourcePosition struct {
	key   Location
	value Location
}

func sourcePositions(b []byte) map[string]sourcePosition {
	var doc yamlv3.Node
	if err := yamlv3.Unmarshal(b, &doc); err != nil {
		return nil
	}
	positions := make(map[string]sourcePosition)
	var walk func(*yamlv3.Node, string)
	walk = func(node *yamlv3.Node, path string) {
		switch node.Kind {
		case yamlv3.DocumentNode:
			if len(node.Content) > 0 {
				walk(node.Content[0], path)
			}
		case yamlv3.MappingNode:
			for i := 0; i+1 < len(node.Content); i += 2 {
				key, value := node.Content[i], node.Content[i+1]
				child := key.Value
				if path != "" {
					child = path + "." + child
				}
				positions[child] = sourcePosition{
					key:   Location{Line: key.Line, Column: key.Column},
					value: Location{Line: value.Line, Column: value.Column},
				}
				walk(value, child)
			}
		case yamlv3.SequenceNode:
			for i, value := range node.Content {
				child := fmt.Sprintf("%s.%d", path, i)
				positions[child] = sourcePosition{value: Location{Line: value.Line, Column: value.Column}}
				walk(value, child)
			}
		}
	}
	walk(&doc, "")
	return positions
}

func errorsResult(file string, err error, positions map[string]sourcePosition) (Result, error) {
	result := Result{Errors: []Error{}}
	for _, ce := range cueerror.Errors(err) {
		location := Location{File: file}
		// CUE may attach schema positions before source positions. Prefer the
		// position in the requested YAML document, even when it is not first.
		for _, pos := range append(ce.InputPositions(), ce.Position()) {
			if pos.IsValid() && (file == "" || pos.Filename() == file) {
				location.Line, location.Column = pos.Line(), pos.Column()
				break
			}
		}
		path := strings.Join(ce.Path(), ".")
		if source, ok := positions[path]; ok {
			if strings.Contains(ce.Error(), "field not allowed") {
				location.Line, location.Column = source.key.Line, source.key.Column
			} else {
				location.Line, location.Column = source.value.Line, source.value.Column
			}
		}
		result.Errors = append(result.Errors, Error{
			Path:     path,
			Message:  ce.Error(),
			Location: location,
		})
	}
	if len(result.Errors) == 0 {
		result.Errors = append(result.Errors, Error{Message: err.Error(), Location: Location{File: file}})
	}
	return result, ErrValidationFailed
}

func writeResult(format string, result Result, dst io.Writer) error {
	if format == jsonFormat {
		return json.NewEncoder(dst).Encode(result)
	}
	if format != textFormat {
		fmt.Fprintln(dst, "Invalid format chosen, defaulting to \"text\" format...")
	}
	if len(result.Errors) == 0 {
		_, err := fmt.Fprintln(dst, "✅ Validation success!")
		return err
	}
	if _, err := fmt.Fprintln(dst, "❌ Validation failure!"); err != nil {
		return err
	}
	for _, e := range result.Errors {
		if _, err := fmt.Fprintf(dst, "\n- %s:%d:%d: %s\n", e.Location.File, e.Location.Line, e.Location.Column, e.Message); err != nil {
			return err
		}
	}
	return nil
}

// ValidateFiles validates every file and writes the aggregated result.
func ValidateFiles(dst io.Writer, files []string, format string) error {
	validator, err := NewFeaturesValidator()
	if err != nil {
		return err
	}
	result := Result{Errors: []Error{}}
	for _, file := range files {
		b, err := os.ReadFile(file)
		if err != nil {
			return fmt.Errorf("read %s: %w", file, err)
		}
		found, err := validator.Validate(file, b)
		if err != nil && !errors.Is(err, ErrValidationFailed) {
			return err
		}
		result.Errors = append(result.Errors, found.Errors...)
	}
	if err := writeResult(format, result, dst); err != nil {
		return err
	}
	if len(result.Errors) > 0 {
		return ErrValidationFailed
	}
	return nil
}
package main

import (
	"errors"
	"fmt"
	"os"

	"github.com/spf13/cobra"
	"go.flipt.io/flipt/internal/cue"
)

type validateCommand struct {
	issueExitCode int
	format        string
}

func newValidateCommand() *cobra.Command {
	v := &validateCommand{}

	cmd := &cobra.Command{
		Use:          "validate",
		Short:        "Validate a list of flipt features.yaml files",
		Run:          v.run,
		Hidden:       true,
		SilenceUsage: true,
	}

	cmd.Flags().IntVar(&v.issueExitCode, "issue-exit-code", 1, "Exit code to use when issues are found")

	cmd.Flags().StringVarP(
		&v.format,
		"format", "F",
		"text",
		"output format",
	)

	return cmd
}

func (v *validateCommand) run(cmd *cobra.Command, args []string) {
	if err := cue.ValidateFiles(os.Stdout, args, v.format); err != nil {
		if errors.Is(err, cue.ErrValidationFailed) {
			os.Exit(v.issueExitCode)
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}
